local addonName, ns = ...

-- Tiles are generated by tools/mapgen/export.py. Tiles.lua sets ns.tiles[uiMapID] = { rows, cols }.
ns.tiles = ns.tiles or {}

local TILE_PATH = "Interface\\AddOns\\ClearMap\\Tiles\\%d\\%d_%d"
local defaults = { enabled = true }

-- Our textures per Blizzard detail layer frame. Kept in our own table so no Blizzard table is written to.
local layerTextures = {}
local button

local function GridFor(mapID)
    return ns.db.enabled and mapID and ns.tiles[mapID]
end

-- Cover a detail layer with our tiles, or give it back to Blizzard's tiles.
local function ApplyLayer(layer, mapID)
    local grid = GridFor(mapID)
    -- Alpha, not Hide: Blizzard keeps the whole layer invisible until its own tiles report loaded.
    for tile in layer.detailTilePool:EnumerateActive() do
        tile:SetAlpha(grid and 0 or 1)
    end
    local list = layerTextures[layer] or {}
    layerTextures[layer] = list
    local used = 0
    if grid then
        local art = C_Map.GetMapArtLayers(mapID)[1]
        local w, h = art.layerWidth / grid.cols, art.layerHeight / grid.rows
        for row = 0, grid.rows - 1 do
            for col = 0, grid.cols - 1 do
                used = used + 1
                local tex = list[used] or layer:CreateTexture(nil, "BACKGROUND", nil, -7)
                list[used] = tex
                tex:ClearAllPoints()
                tex:SetPoint("TOPLEFT", layer, "TOPLEFT", col * w, -row * h)
                tex:SetSize(w, h)
                tex:SetTexture(TILE_PATH:format(mapID, row, col), nil, nil, "TRILINEAR")
                tex:Show()
            end
        end
    end
    for i = used + 1, #list do
        list[i]:Hide()
    end
end

-- The explored-area overlays are Blizzard art drawn on top of the base tiles. Hide them on our maps.
local function ApplyExploration(pin, mapID)
    pin:SetShown(not GridFor(mapID))
end

local function Refresh()
    local map = WorldMapFrame
    local mapID = map:GetMapID()
    for layer in map.detailLayerPool:EnumerateActive() do
        ApplyLayer(layer, mapID)
    end
    for pin in map:EnumeratePinsByTemplate("MapExplorationPinTemplate") do
        ApplyExploration(pin, mapID)
    end
    if button then
        button:SetText(ns.db.enabled and "ClearMap: On" or "ClearMap: Off")
        button:SetShown(ns.tiles[mapID] ~= nil)
    end
end

local function Toggle()
    ns.db.enabled = not ns.db.enabled
    Refresh()
end

local function Setup()
    local map = WorldMapFrame
    hooksecurefunc(map, "RefreshDetailLayers", Refresh)
    for pin in map:EnumeratePinsByTemplate("MapExplorationPinTemplate") do
        hooksecurefunc(pin, "RefreshOverlays", function(p)
            ApplyExploration(p, map:GetMapID())
        end)
    end

    button = CreateFrame("Button", nil, map.ScrollContainer, "UIPanelButtonTemplate")
    button:SetSize(110, 22)
    button:SetPoint("BOTTOMLEFT", map.ScrollContainer, "BOTTOMLEFT", 8, 8)
    button:SetFrameLevel(map.ScrollContainer:GetFrameLevel() + 50)
    button:SetScript("OnClick", Toggle)
    Refresh()
end

local frame = CreateFrame("Frame")
frame:SetScript("OnEvent", function(self, event, ...)
    self[event](self, ...)
end)
frame:RegisterEvent("ADDON_LOADED")
frame:RegisterEvent("PLAYER_LOGIN")

function frame:ADDON_LOADED(name)
    if name == addonName then
        ClearMapDB = ClearMapDB or {}
        for key, value in pairs(defaults) do
            if ClearMapDB[key] == nil then
                ClearMapDB[key] = value
            end
        end
        ns.db = ClearMapDB
    elseif name == "Blizzard_WorldMap" and ns.db and not button then
        Setup()
    end
end

function frame:PLAYER_LOGIN()
    if WorldMapFrame and not button then
        Setup()
    end
end

SLASH_CLEARMAP1 = "/clearmap"
SlashCmdList.CLEARMAP = function()
    Toggle()
    print(addonName .. ": " .. (ns.db.enabled and "on" or "off"))
end
